package com.vibeguard.samples.timesheets; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.LocalDate; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Allows authenticated staff to record and read their own working hours. */ @RestController @RequestMapping("/internal/timesheets") public class TimesheetController { private final Map<String,List<Entry>> entries=new ConcurrentHashMap<>(); @Value("${STAFF_TIMESHEET_KEY:}") private String staffKey; @PostMapping("/{staffId}") public ResponseEntity<Entry> log(@RequestHeader("X-Staff-Timesheet-Key") String key,@PathVariable String staffId,@Valid @RequestBody Request request){if(!allowed(key))return ResponseEntity.status(401).build();Entry entry=new Entry(LocalDate.now(),request.hours(),request.description());entries.computeIfAbsent(staffId,ignored->new ArrayList<>()).add(entry);return ResponseEntity.status(201).body(entry);}@GetMapping("/{staffId}") public ResponseEntity<List<Entry>> list(@RequestHeader("X-Staff-Timesheet-Key") String key,@PathVariable String staffId){return allowed(key)?ResponseEntity.ok(List.copyOf(entries.getOrDefault(staffId,List.of()))):ResponseEntity.status(401).build();}private boolean allowed(String key){return !staffKey.isBlank()&&staffKey.equals(key);}record Request(@DecimalMin("0.25") @DecimalMax("24") double hours,@NotBlank String description){}record Entry(LocalDate date,double hours,String description){} }
